import math
# rhombus with diagonals along axes: P(-3,0) R(3,0) Q(0,-2) S(0,2)
P=(-3,0);R=(3,0);Q=(0,-2);S=(0,2)
def ang(O):
    a=(S[0]-O[0],S[1]-O[1]);b=(Q[0]-O[0],Q[1]-O[1])
    c=(a[0]*b[0]+a[1]*b[1])/(math.hypot(*a)*math.hypot(*b))
    return round(math.degrees(math.acos(max(-1,min(1,c)))),6)
for y in (0.5,-1.0,1.5):
    assert abs(ang((0,y))-180)<1e-4
    assert math.isclose(math.dist((0,y),P),math.dist((0,y),R))
opts={'A':240,'B':120,'C':180,'D':200}
assert ang((0,0.5))==opts['C']
for k in 'ABD': assert ang((0,0.5))!=opts[k]

