letters=['A','L','K','M']
def nxt(fig):
    # each step all rays rotate 45 deg clockwise and a new ray appears at top
    return {k:v+45 for k,v in fig.items()}
f4={'M':0,'K':45,'L':90,'A':135}
f5=nxt(f4)
opts={'A':{'M':0,'K':90,'L':135,'A':180},'B':{'H':0,'M':45,'K':90,'L':135,'A':180},'C':{'M':45,'K':90,'L':135,'A':180},'D':{'M':0,'K':45,'L':90,'A':135}}
def fits(o):
    rest={k:v for k,v in o.items() if k in f5}
    new=[k for k in o if k not in f5]
    return rest==f5 and len(new)==1 and o[new[0]]==0
assert [k for k in opts if fits(opts[k])]==['B']

