# pluses and triangles each increase by 1; triangles fill left side (max 3) then bottom
def fig(n):
    return {'tri_left':min(n,3),'tri_bottom':max(0,n-3),'plus':n}
f=fig(5)
opts={'A':{'tri_left':3,'tri_bottom':1,'plus':4},'B':{'tri_left':3,'tri_bottom':2,'plus':4},
'C':{'tri_left':3,'tri_bottom':2,'plus':5},'D':{'tri_left':3,'tri_bottom':1,'plus':4}}
assert fig(4)=={'tri_left':3,'tri_bottom':1,'plus':4}
assert [k for k in opts if opts[k]==f]==['C']

